#include <cassert>
#include <iostream>
#include <utility>

int calls = 0;
void risky() {
    ++calls;
    throw 7;
}

int contained() noexcept {
    try {
        risky();
    } catch (int) {
        return 42;
    }
    return 0;
}

template<class F>
void invoke(F&& f) noexcept(noexcept(std::forward<F>(f)())) {
    std::forward<F>(f)();
}

int main() {
    static_assert(!noexcept(risky()));
    static_assert(noexcept(contained()));
    static_assert(noexcept(invoke([]() noexcept {})));
    static_assert(!noexcept(invoke([]() {})));
    const bool answer = noexcept(risky());
    assert(!answer && calls == 0);
    assert(contained() == 42);
    assert(calls == 1);
    std::cout << "42 1\n";
}

