struct Item {
    inline static int allocations = 0;
    inline static int deallocations = 0;
    inline static int destructions = 0;
    static void* operator new(std::size_t n) {
        void* p = ::operator new(n);
        ++allocations;
        return p;
    }
    static void operator delete(void* p) noexcept {
        ++deallocations;
        ::operator delete(p);
    }
    explicit Item(bool fail) {
        if (fail) throw std::runtime_error("construction failed");
    }
    ~Item() { ++destructions; }
};

int main() {
    try {
        Item* p = new Item(true);
        delete p;
    } catch (const std::runtime_error&) {}
    assert(Item::allocations == 1 && Item::deallocations == 1);
    assert(Item::destructions == 0);
    Item* p = new Item(false);
    delete p;
    assert(Item::allocations == 2 && Item::deallocations == 2);
    assert(Item::destructions == 1);
    std::cout << "construction cleanup checked\n";
}

