struct Failure {};

void append_pair(std::vector<int>& values, bool fail) {
    auto prepared = values;
    prepared.push_back(20);
    if (fail) throw Failure{};
    prepared.push_back(30);
    static_assert(noexcept(values.swap(prepared)));
    values.swap(prepared);
}

int main() {
    std::vector<int> values{10};
    const auto before = values;
    try {
        append_pair(values, true);
        assert(false);
    } catch (const Failure&) {
        assert(values == before);
    }
    append_pair(values, false);
    assert((values == std::vector<int>{10, 20, 30}));
    std::cout << "10 20 30\n";
}

