    int observed = 0;
    bool recovered = false;
    try {
        Cleanup cleanup{observed, recovered};
        throw 1;
    } catch (int value) {
        assert(value == 1);
        assert(std::uncaught_exceptions() == 0);
    }
    assert(observed == 1 && recovered);
    std::cout << "outer caught; cleanup recovered\n";
}

