#include <atomic>
#include <cassert>
#include <iostream>
#include <mutex>
#include <thread>
class SpinLock {
    std::atomic_flag busy = ATOMIC_FLAG_INIT;
public:
    void lock() noexcept {
        while (busy.test_and_set(std::memory_order_acquire)) {
            std::this_thread::yield();
        }
    }
    void unlock() noexcept { busy.clear(std::memory_order_release); }
};
int main() {
    SpinLock m;
    int total = 0;
    auto work = [&] {
        for (int i = 0; i < 1000; ++i) {
            std::lock_guard guard(m);
            ++total;
        }
    };
    std::jthread a(work);
    std::jthread b(work);
    a.join();
    b.join();
    assert(total == 2000);
    std::cout << total << '\n';
}

