#include <cassert>
#include <cstddef>

class Slots {
    std::size_t limit_;
    std::size_t used_ = 0;
public:
    explicit Slots(std::size_t limit) : limit_(limit) {}
    bool acquire() {
        if (used_ == limit_) return false;
        ++used_;
        return true;
    }
    bool release() {
        if (used_ == 0) return false;
        --used_;
        return true;
    }
    std::size_t available() const { return limit_ - used_; }
};

int main() {
    Slots slots(1);
    assert(slots.acquire());
    assert(!slots.acquire());
    assert(slots.available() == 0);
    assert(slots.release());
    assert(!slots.release());
    assert(slots.available() == 1);
}

