struct Invalid {};
struct Failure {};
struct State {
    std::string name;
    int retries;
};

void replace_state(std::unique_ptr<State>& current,
                   std::string name, int retries, bool fail) {
    if (name.empty() || retries < 1) throw Invalid{};
    auto prepared = std::make_unique<State>(
        State{std::move(name), retries});
    if (fail) throw Failure{};
    current.swap(prepared);
}

int main() {
    auto current = std::make_unique<State>(State{"old", 1});
    try {
        replace_state(current, "new", 3, true);
        assert(false);
    } catch (const Failure&) {
        assert(current->name == "old" && current->retries == 1);
    }
    replace_state(current, "new", 3, false);
    assert(current->name == "new" && current->retries == 3);
    std::cout << "new 3\n";
}

