#include <cassert>
#include <iostream>
#include <memory>
struct Node {
    int key;
    std::unique_ptr<Node> left, right;
    explicit Node(int k) : key(k) {}
};
void insert(std::unique_ptr<Node>& root, int key) {
    auto* link = &root;
    while (*link) {
        if (key == (*link)->key) return;
        link = key < (*link)->key ? &(*link)->left : &(*link)->right;
    }
    *link = std::make_unique<Node>(key);
}
int visits(const Node* p, int key) {
    int count = 0;
    while (p) {
        ++count;
        if (key == p->key) break;
        p = key < p->key ? p->left.get() : p->right.get();
    }
    return count;
}
int main() {
    std::unique_ptr<Node> chain, balanced;
    for (int x : {1, 2, 3, 4, 5, 6, 7}) insert(chain, x);
    for (int x : {4, 2, 6, 1, 3, 5, 7}) insert(balanced, x);
    assert(visits(chain.get(), 7) == 7);
    assert(visits(balanced.get(), 7) == 3);
    std::cout << visits(chain.get(), 7) << ' '
              << visits(balanced.get(), 7) << '\n';
}

