#include <algorithm>
#include <cassert>
#include <cmath>
#include <iostream>
#include <limits>
static_assert(std::numeric_limits<double>::max_exponent >
              std::numeric_limits<float>::max_exponent);
bool close(float a, float b, double abs_tol, double rel_tol) {
    assert(std::isfinite(abs_tol) && std::isfinite(rel_tol));
    assert(abs_tol >= 0 && rel_tol >= 0 && rel_tol <= 1);
    if (a == b) return true;
    if (!std::isfinite(a) || !std::isfinite(b)) return false;
    double da = a, db = b;
    return std::fabs(da - db) <=
        std::max(abs_tol, rel_tol * std::max(std::fabs(da), std::fabs(db)));
}
int main() {
    bool near_zero = close(0.0f, 0.00000001f, 1e-7, 1e-5);
    bool near_large = close(1000000.0f, 1000001.0f, 1e-7, 1e-5);
    bool far = close(1.0f, 1.01f, 1e-7, 1e-5);
    assert(near_zero && near_large && !far);
    std::cout << std::boolalpha << near_zero << ' ' << near_large << ' ' << far << '\n';
}

