long long make_cents(long long units, unsigned fraction) {
    if (units < 0 || fraction >= 100) throw std::invalid_argument("amount");
    const auto limit = std::numeric_limits<long long>::max();
    if (units > (limit - fraction) / 100) throw std::overflow_error("amount");
    return units * 100 + fraction;
}
int main() {
    auto price = make_cents(12, 34);
    std::map<long long, std::string> catalog;
    catalog.emplace(price, "item");
    assert(price == 1234);
    assert(catalog.at(make_cents(12, 34)) == "item");
    std::cout << price << ' ' << catalog.at(price) << '\n';
}

