struct Box { std::mutex m; int value = 1000; };
void transfer(Box& from, Box& to) {
    if (&from == &to) return;
    std::scoped_lock guard(from.m, to.m);
    --from.value;
    ++to.value;
}
int main() {
    Box a, b;
    std::jthread x([&] { for (int i=0; i<100; ++i) transfer(a,b); });
    std::jthread y([&] { for (int i=0; i<100; ++i) transfer(b,a); });
    x.join();
    y.join();
    assert(a.value == 1000 && b.value == 1000);
    std::cout << a.value + b.value << '\n';
}

