std::array<unsigned char, 4> encode(std::uint32_t v) {
    return {static_cast<unsigned char>(v >> 24),
            static_cast<unsigned char>(v >> 16),
            static_cast<unsigned char>(v >> 8),
            static_cast<unsigned char>(v)};
}
std::uint32_t decode(const std::array<unsigned char,4>& b) {
    return (std::uint32_t{b[0]} << 24) |
           (std::uint32_t{b[1]} << 16) |
           (std::uint32_t{b[2]} << 8) | std::uint32_t{b[3]};
}
int main() {
    static_assert(CHAR_BIT == 8);
    auto bytes = encode(0x01020304u);
    assert((bytes == std::array<unsigned char,4>{1,2,3,4}));
    assert(decode(bytes) == 0x01020304u);
    for (auto b : bytes) std::cout << unsigned(b) << ' ';
    std::cout << '\n';
}

#include <cassert>
