template<class T>
class Owner {
    static_assert(!std::is_bounded_array_v<T>);
    using Element = std::remove_extent_t<T>;
    Element* p_;
public:
    explicit Owner(Element* p = nullptr) noexcept : p_(p) {}
    ~Owner() { std::default_delete<T>{}(p_); }
    Owner(const Owner&) = delete;
    Owner& operator=(const Owner&) = delete;
    Owner(Owner&& other) noexcept : p_(other.release()) {}
    Owner& operator=(Owner&& other) noexcept {
        if (this != &other) reset(other.release());
        return *this;
    }
    Element* get() const noexcept { return p_; }
    Element* release() noexcept { return std::exchange(p_, nullptr); }
    void reset(Element* next = nullptr) noexcept {
        std::default_delete<T>{}(std::exchange(p_, next));
    }
};

struct Item {
    inline static int alive = 0;
    Item() { ++alive; }
    ~Item() { --alive; }
};

int main() {
    {
        Owner<Item> one(new Item);
        Owner<Item[]> many(new Item[3]);
        Owner<Item[]> moved(std::move(many));
        assert(many.get() == nullptr);
        assert(moved.get() != nullptr);
        assert(Item::alive == 4);
    }
    assert(Item::alive == 0);
    std::cout << "all four destroyed\n";
}

#include <cassert>
#include <iostream>
#include <memory>

struct Node {
    inline static int alive = 0;
    std::shared_ptr<Node> next;
    Node() { ++alive; }
    ~Node() { --alive; }
};

int main() {
    std::weak_ptr<Node> rescue;
    {
        auto a = std::make_shared<Node>();
        auto b = std::make_shared<Node>();
        a->next = b;
        b->next = a;
        rescue = a;
    }
    assert(Node::alive == 2);
    auto a = rescue.lock();
    assert(a);
    a->next.reset();
    assert(Node::alive == 1);
    a.reset();
    assert(Node::alive == 0 && rescue.expired());
    std::cout << "cycle broken\n";
}

