#include <unordered_map>
struct Point {
    int x, y;
    bool operator==(const Point&) const = default;
};
struct PointLess {
    bool operator()(const Point& a, const Point& b) const {
        return std::tie(a.x, a.y) < std::tie(b.x, b.y);
    }
};
struct PointHash {
    std::size_t operator()(const Point& p) const {
        auto h1 = std::hash<int>{}(p.x);
        auto h2 = std::hash<int>{}(p.y);
        return h1 ^ (h2 + std::size_t{0x9e3779b9} + (h1 << 6) + (h1 >> 2));
    }
};
int main() {
    std::map<Point, int, PointLess> ordered;
    std::unordered_map<Point, int, PointHash> hashed;
    ordered.emplace(Point{2, 3}, 7);
    hashed.emplace(Point{2, 3}, 7);
    assert(ordered.at(Point{2, 3}) == 7);
    assert(hashed.at(Point{2, 3}) == 7);
    std::cout << hashed.at(Point{2, 3}) << '\n';
}

