namespace model {
    struct Item { int value; };
    inline unsigned swaps = 0;
    int weight(const Item& x) { return x.value; }
    void swap(Item& a, Item& b) noexcept {
        ++swaps;
        std::swap(a.value, b.value);
    }
}
template<class T>
void exchange_values(T& a, T& b) {
    using std::swap;
    swap(a, b);
}
int main() {
    model::Item a{2}, b{7};
    assert(weight(a) == 2);
    exchange_values(a, b);
    assert(a.value == 7 && b.value == 2 && model::swaps == 1);
    int x = 1, y = 3;
    exchange_values(x, y);
    assert(x == 3 && y == 1);
}

