int main() {
    std::atomic<std::shared_ptr<const int>> current;
    current.store(std::make_shared<const int>(7));
    std::thread reader([&] {
        auto snapshot = current.load();
        assert(snapshot && (*snapshot == 7 || *snapshot == 9));
