struct Guard {
    int id;
    std::array<int, 3>& events;
    int& count;
    ~Guard() noexcept { events[count++] = id; }
};

void nested(std::array<int, 3>& events, int& count) {
    Guard inner{2, events, count};
    throw 7;
}

int main() {
    std::array<int, 3> events{};
    int count = 0;
    {
        Guard outside{0, events, count};
        try {
            Guard local{1, events, count};
            nested(events, count);
        } catch (int value) {
            assert(value == 7);
            assert(count == 2);
            assert(events[0] == 2 && events[1] == 1);
        }
        assert(count == 2);
    }
    assert(count == 3 && events[2] == 0);
    std::cout << events[0] << ' ' << events[1]
              << ' ' << events[2] << '\n';
}

