struct Block { std::size_t size; bool free; };

int main() {
    const std::array<Block, 4> blocks{{
        {64, true}, {32, false}, {64, true}, {32, false}
    }};
    std::size_t total = 0;
    std::size_t largest = 0;
    for (const auto& block : blocks) {
        if (block.free) {
            total += block.size;
            largest = std::max(largest, block.size);
        }
    }
    assert(total == 128 && largest == 64);
    const bool fits = largest >= 96;
    assert(!fits);
    std::cout << "free=" << total << " largest=" << largest
              << " fits96=" << std::boolalpha << fits << '\n';
}

#include <cassert>
#include <cstddef>
#include <iostream>
#include <vector>

struct Node {
    std::vector<std::size_t> edges;
    bool marked = false;
};

int main() {
    std::vector<Node> heap{
        Node{{1}}, Node{{0}}, Node{{3}}, Node{{2}}
    };
    std::vector<std::size_t> pending{0};
    while (!pending.empty()) {
        const auto index = pending.back();
        pending.pop_back();
        auto& node = heap[index];
        if (node.marked) continue;
        node.marked = true;
        for (auto edge : node.edges) pending.push_back(edge);
    }
    std::size_t reachable = 0;
    for (const auto& node : heap) reachable += node.marked ? 1 : 0;
    assert(reachable == 2);
    std::cout << "reachable=" << reachable
              << " collectible=" << heap.size() - reachable << '\n';
}

#include <cassert>

struct Probe {
    virtual bool reachable(int target) = 0;
    virtual ~Probe() = default;
};
class Scanner {
    Probe& probe_;
public:
    explicit Scanner(Probe& probe) : probe_(probe) {}
    int count_two() {
        int count = 0;
        if (probe_.reachable(1)) ++count;
        if (probe_.reachable(2)) ++count;
        return count;
    }
};
struct FakeProbe final : Probe {
    bool reachable(int target) override { return target == 2; }
};
int main() {
    FakeProbe fake;
    Scanner scanner(fake);
    assert(scanner.count_two() == 1);
}

