template<class Predicate>
std::size_t count_matching(std::span<const int> values, Predicate accept) {
    std::size_t count = 0;
    for (int value : values) {
        if (accept(value)) ++count;
    }
    return count;
}
int main() {
    const std::array data{1, 2, 3, 4};
    assert(count_matching(std::span<const int>{data},
                          [](int x) { return x % 2 == 0; }) == 2);
    assert(count_matching(std::span<const int>{data},
                          [](int x) { return x > 1; }) == 3);
}

#include <cassert>
#include <cstddef>
#include <optional>

struct Bag {
    // true: элемент добавлен; false: состояние не изменено.
    virtual bool try_add(int value) = 0;
    virtual std::size_t size() const = 0;
    virtual ~Bag() = default;
};
struct OneSlot final : Bag {
    std::optional<int> item;
    bool try_add(int value) override {
        if (item) return false;
        item = value;
        return true;
    }
    std::size_t size() const override { return item ? 1u : 0u; }
};
void contract_test(Bag& bag) {
    auto before = bag.size();
    bool added = bag.try_add(7);
    assert(bag.size() == before + (added ? 1u : 0u));
}
int main() {
    OneSlot bag;
    contract_test(bag);
    contract_test(bag);
    assert(bag.item == 7);
}

#include <cassert>
#include <optional>
#include <string_view>

std::optional<unsigned> parse_port(std::string_view text) {
    if (text.empty()) return std::nullopt;
    unsigned value = 0;
    for (char ch : text) {
        if (ch < '0' || ch > '9') return std::nullopt;
        unsigned digit = static_cast<unsigned>(ch - '0');
        if (value > (65535u - digit) / 10u) return std::nullopt;
        value = value * 10u + digit;
    }
    if (value == 0) return std::nullopt;
    return value;
}
int main() {
    assert(parse_port("1") == 1u);
    assert(parse_port("65535") == 65535u);
    assert(!parse_port(""));
    assert(!parse_port("0"));
    assert(!parse_port("65536"));
    assert(!parse_port("12x"));
    assert(!parse_port("-1"));
    assert(!parse_port("999999999999999999999"));
}

