#include <cassert>
#include <cstddef>
#include <utility>

class Interval {
    std::size_t first_ = 0;
    std::size_t last_ = 0;
public:
    bool set(std::size_t first, std::size_t last) {
        if (first > last) return false;
        first_ = first;
        last_ = last;
        return true;
    }
    std::size_t length() const { return last_ - first_; }
    std::pair<std::size_t, std::size_t> bounds() const {
        return {first_, last_};
    }
};
int main() {
    Interval interval;
    assert(interval.set(3, 8));
    assert(interval.length() == 5);
    auto before = interval.bounds();
    assert(!interval.set(9, 2));
    assert(interval.bounds() == before);
}

