    void increment() { ++value_; }
public:
    unsigned value() const { return value_; }
};
class Worker : private Counter {
public:
    void work() { increment(); }
    unsigned completed() const { return Counter::value(); }
};
int main() {
    static_assert(!std::is_convertible_v<Worker*, Counter*>);
    Worker worker;
    worker.work();
    worker.work();
    assert(worker.completed() == 2);
}

