using Byte = unsigned char;
using Values = std::list<Byte>;
std::vector<Byte> encode(const Values& values) {
    if (values.size() > 255) throw std::length_error("too many values");
    std::vector<Byte> bytes{static_cast<Byte>(values.size())};
    bytes.insert(bytes.end(), values.begin(), values.end());
    return bytes;
}
bool decode(const std::vector<Byte>& bytes, Values& out) {
    if (bytes.empty() || bytes.size() != 1 + std::size_t(bytes[0])) return false;
    Values temporary(bytes.begin() + 1, bytes.end());
    out.swap(temporary);
    return true;
}
int main() {
    static_assert(CHAR_BIT == 8);
    Values original{4, 9, 4};
    auto bytes = encode(original);
    assert((bytes == std::vector<Byte>{3, 4, 9, 4}));
    Values restored;
    const bool decoded = decode(bytes, restored);
    assert(decoded);
    assert(restored == original);
    const bool malformed_decoded = decode({3, 4}, restored);
    assert(!malformed_decoded);
    assert(restored == original);
    for (Byte value : restored) std::cout << unsigned(value) << ' ';
    std::cout << '\n';
}

