#include <cassert>
#include <cstddef>
#include <iostream>
#include <memory>
#include <mutex>

class Limited {
    inline static std::mutex mutex_;
    inline static std::size_t alive_ = 0;
    static constexpr std::size_t limit_ = 2;
    Limited() = default;
public:
    Limited(const Limited&) = delete;
    Limited& operator=(const Limited&) = delete;
    Limited(Limited&&) = delete;
    Limited& operator=(Limited&&) = delete;
    ~Limited() {
        std::lock_guard lock(mutex_);
        assert(alive_ > 0);
        --alive_;
    }
    static std::unique_ptr<Limited> create() {
        std::lock_guard lock(mutex_);
        if (alive_ == limit_) return {};
        std::unique_ptr<Limited> result(new Limited);
        ++alive_;
        return result;
    }
};

int main() {
    auto first = Limited::create();
    auto second = Limited::create();
    auto rejected = Limited::create();
    assert(first && second && !rejected);
    first.reset();
    auto replacement = Limited::create();
    assert(replacement);
    std::cout << "limit checked\n";
}

